        var threads = { data: { repository: { pullRequest: { reviewThreads: {
            nodes: [threadNode('ai-teammate', false), threadNode('ai-teammate', false),
                    threadNode('ai-teammate', false), threadNode('ai-teammate', false)] } } } } };
