    test('AC3 — only machine-authored unresolved threads count: unresolved HUMAN threads + a consumption → no restore', function () {
        var sm = makeSmAgent({
            fileMap: { '../.dmtools/config.js': 'module.exports = { repository: { owner: "epam", repo: "dmtools-agents" } };' },
            github: {
                items: [pr826()],
