    // callers ask for the NEWEST marker — payload order alone is arbitrary
    // when several markers carry the same clock tick.
    out.sort(function (a, b) {
        var aTime = isNaN(a.atMs) ? -1 : a.atMs;
        var bTime = isNaN(b.atMs) ? -1 : b.atMs;
