        return false;
    }
    if (consultReworkLatch(key, ticket, repoInfo).latched) return false;
    var head = reworkLatchHeadOf(ticket);
    if (head && hasActiveLegRun(headWorkflowRunsSafe(repoInfo, head),
            reworkLatchModule.DEFAULT_LEG_WORKFLOW)) {
