function tickReworkLatchState(effectiveRepoInfo) {
    if (tickReworkLatch) return tickReworkLatch;
    var state = { map: {} };
    var cfg = reworkLatchStateCfg();
    var repoInfo = null;
    if (cfg) {
        if (cfg.repo) {
            var parts = String(cfg.repo).split('/');
            repoInfo = { owner: parts[0], repo: parts[1] };
        } else {
            repoInfo = effectiveRepoInfo || null;
        }
    }
    if (cfg && repoInfo && repoInfo.owner && repoInfo.repo) {
        try {
            var prev = factoryStateModule.fetchPreviousState(
                repoInfo.owner + '/' + repoInfo.repo, cfg,
                function (a) { return cli_execute_command(a); });
            if (prev && prev.reworkInFlight) {
                state.map = reworkLatchModule.normalizeMap(prev.reworkInFlight);
            }
        } catch (eLatchPrev) {
            // Any miss (first tick, 404, rate limit) → empty map: the armer
            // keeps today's behavior and the snapshot re-seeds the latch.
        }
    }
    tickReworkLatch = state;
    return tickReworkLatch;
}

function reworkLatchHeadOf(ticket) {
    return (ticket && ticket.pr && ticket.pr.headSha) ||
        (ticket && ticket.headSha) || null;
}

/**
 * The AC1 gate — is a rework leg already in flight for (ticket.prNumber,
 * head)? Returns { latched, head }; the caller must arm/dispatch NOTHING
 * when latched. The canonical suppression line
 * `⏭️ <key> rework already in flight for (pr-N, head7)` is logged HERE,
 * exactly once per suppressed decision.
 * Side effects on a PRESENT latch: one head-runs probe decides its fate —
 * an ACTIVE leg run keeps it alive past the stale window (the leg really
 * is flying), a CONCLUDED leg run at/after the arm clears it (AC2), no run
 * + older than 45 min self-heals (AC3). A null probe (failed gh call)
 * degrades to age-only — fail-safe toward suppressing one extra arm,
 * never toward stacking legs. The clear is logged with its cause.
 */
function consultReworkLatch(key, ticket, effectiveRepoInfo) {
    var prNumber = ticket && ticket.prNumber;
    var head = reworkLatchHeadOf(ticket);
    if (!prNumber || !head) return { latched: false, head: head };
    var latchState = tickReworkLatchState(effectiveRepoInfo);
    var verdict = reworkLatchModule.isActive(latchState.map, prNumber, head, {});
    if (verdict.entry) {
        var runs = headWorkflowRunsSafe(effectiveRepoInfo, head);
        verdict = reworkLatchModule.isActive(latchState.map, prNumber, head, {
            runs: runs,
            workflowFile: reworkLatchModule.DEFAULT_LEG_WORKFLOW
        });
    }
    if (!verdict.active) {
        if (verdict.entry) {
            reworkLatchModule.clear(latchState.map, prNumber, head);
            console.log('  🔓 ' + key + ' rework latch cleared (' + verdict.cause +
                ') for (pr-' + prNumber + ', ' + head.substring(0, 7) + ')');
        }
        return { latched: false, head: head };
    }
    console.log('  ⏭️  ' + key + ' rework already in flight for (pr-' + prNumber +
        ', ' + head.substring(0, 7) + ')');
    return { latched: true, head: head };
}

/**
 * Record an arming decision (gh-806): from now on, one leg for (pr, head).
 * DRY never arms (the dry tick publishes nothing — arming a map that never
 * persists would silently swallow the NEXT real tick's first arm).
 */
function armReworkLatch(ticket) {
    if (DRY) return;
    var prNumber = ticket && ticket.prNumber;
    var head = reworkLatchHeadOf(ticket);
    if (!prNumber || !head) return;
    var latchState = tickReworkLatchState(null);
    reworkLatchModule.arm(latchState.map, prNumber, head, null, 'sm');
}

function action(params) {
    var p     = params.jobParams || params;
    RUN_JOB_PARAMS = p;    DRY = p.dryRun === true;
    tickReworkLatch = null;
    if (DRY) console.log('🧪 DRY RUN — no side effects will be performed');
    var rules = p.rules;

    // Load global project configuration (used as default when rules have no configPath)
    projectConfig = configLoader.loadProjectConfig(p);

    var configuredWorkflowCap = resolveWorkflowCap(
        typeof p.maxTriggeredWorkflows !== 'undefined' ? p.maxTriggeredWorkflows : p.maxWorkflowsPerRun,
        projectConfig
    );
    var workflowBudget = configuredWorkflowCap ? { initial: configuredWorkflowCap, remaining: configuredWorkflowCap } : null;

    // Priority-tier label names (owner directive 2026-10-08) — one resolve
    // per tick; every rule query below carries them via ctx.priorityLabels.
    PRIORITY_LABELS = resolvePriorityLabels(projectConfig);

    // Use smRules from config if provided (full override)
    if (projectConfig.smRules && Array.isArray(projectConfig.smRules) && projectConfig.smRules.length > 0) {
        console.log('SM Agent: Using smRules override from project config (' + projectConfig.smRules.length + ' rules)');

/**
 * reworkConsumption.js — fail-closed `agent:rework` consumption bookkeeping
 * and the consumed-without-work sweep decision (gh-840).
 *
 * Live pathology (dmtools-agents PR #826 / gh-825, 2026-10-10 ~10:00Z):
 * `agent:rework` was armed (twice, comments present) and later CONSUMED —
 * yet no rework leg ever ran, no fix commit landed on the head, 4/6 review
 * threads stayed unresolved and no closing bookkeeping comment existed.
 * Root cause: the PR-carrier rule's `consumeLabels` removes the label on
 * dispatch (or on the gh-715 cross-anchor suppression — any leg in flight
 * under the other anchor "fulfills" the request, even a REVIEW leg), with
 * nothing recording the consumption and nothing verifying a leg-close
 * marker. The armer that should have recovered (arm_rework /
 * rework-unresolved-threads) is withheld in this state (gh-806 latch,
 * gh-807 verdict gate, agent:review notLabels), so the arm never returned:
 * 4h+ hang.
 *
 * This module is the pure side of the fix:
 *
 *   Audit log  — every consumption posts ONE machine-parseable marker
 *                comment on the PR recording its path (dispatch |
 *                cross-anchor), the head sha and a timestamp. Markers are
 *                trusted only from machine identities (the same allowlist
 *                doctrine as reviewVerdicts.js — the format is public).
 *   Sweep      — shouldRestoreArm(): a PR with unresolved MACHINE review
 *                threads, no agent:rework label, no rework in flight,
 *                evidence of a prior consumption (consume/restore marker),
 *                the head NOT advanced past the consumed head (a real push
 *                is the close marker), quiet longer than staleMs (default
 *                30 min ≈ 6 ticks at a ~5-min cron) → restore the arm.
 *                Fail-closed everywhere: no evidence, no restore (AC3 —
 *                human-thread-only PRs are untouched); no clock, no
 *                restore.
 *
 * Pure module — no dmtools globals; smAgent feeds it comment payloads and
 * applies the decisions. GraalJS-clean (var + plain functions, JSON-safe
 * data only).
 */
'use strict';

// gh-840 AC1 bound: N ticks. The SM cron ticks every ~5 min; 30 min = 6
// ticks — the ticket's "≤6 ticks" self-heal bound. Deployment-tunable via
// the rule's staleMinutes knob (same shape as sweep_stale_validation).
var DEFAULT_RESTORE_STALE_MS = 30 * 60 * 1000;

// The consumption audit marker — one line, JSON payload, invisible in the
// rendered PR (same protocol family as the gh-807 verdict marker).
var CONSUME_MARKER_PREFIX = '<!-- dmtools:rework-consume ';
var RESTORE_MARKER_PREFIX = '<!-- dmtools:rework-restore ';
var MARKER_SUFFIX = ' -->';

// The only legal consumption paths (the guard vocabulary):
//   'dispatch'      — consumeLabels fired after an accepted workflow_dispatch
//   'cross-anchor'  — consumeLabels fired after the gh-715 cross-anchor
//                     suppression consumed the request
var CONSUME_PATHS = ['dispatch', 'cross-anchor'];

function isLegalConsumePath(path) {
    return CONSUME_PATHS.indexOf(path) !== -1;
}

/**
 * Builds the consumption-audit comment body. path must be one of
 * CONSUME_PATHS; headSha anchors the consumption to the head it was
 * supposed to rework (the sweep's close-proof check compares the recorded
 * head against the live head). Returns null on an unbuildable record —
 * callers skip the post; an unattributed consumption must never exist.
 */
function buildConsumeAuditComment(path, headSha, atIso) {
    if (!isLegalConsumePath(path)) return null;
    if (!headSha || typeof headSha !== 'string') return null;
    var payload = {
        path: path,
        head: headSha,
        at: atIso || new Date().toISOString()
