    function threadNode(author, resolved) {
        return { id: 'thread-1', isResolved: !!resolved,
                 comments: { nodes: [{ databaseId: 1, author: { login: author }, body: '🚨 BLOCKING: normTokenRow drops cacheRead' }] } };
    }

