// toward hiding it).
function hasConcludedLegRunAtOrAfter(runs, workflowFile, sinceMs) {
    var suffix = '/' + String(workflowFile || 'ai-teammate.yml');
    return (runs || []).some(function (r) {
        if (!r) return false;
        if (r.status !== 'completed') return false;
        var p = String(r.path || '');
        if (p.length < suffix.length ||
            p.slice(p.length - suffix.length) !== suffix) return false;
        var startTs = Date.parse(r.created_at || '');
        return !isNaN(startTs) && !isNaN(sinceMs) && startTs >= sinceMs;
    });
}

