// gh-841 review round 1 (IMPORTANT): the close-proof corroboration for the
// gh-840 sweep's head-advanced branch. A SILENT branch refresh
// (silentUpdateBranch) pushes a merge commit that advances the head
// WITHOUT resolving threads or running a leg — so an advanced head alone
// is not the AC2 close proof. Only a CONCLUDED leg run on the current
// head, STARTED at/after the consumption timestamp, corroborates it: a
// rework leg concluding on this head is what a real close looks like.
// Takes the pre-fetched head rollup (headRuns above); a null (failed
// probe) or unparsable sinceMs reads as NO corroboration — the sweep then
// falls through to the restore check (fail toward catching the hang, not
// toward hiding it).
function hasConcludedLegRunAtOrAfter(runs, workflowFile, sinceMs) {
    var suffix = '/' + String(workflowFile || 'ai-teammate.yml');
    return (runs || []).some(function (r) {
        if (!r) return false;
        if (r.status !== 'completed') return false;
        var p = String(r.path || '');
        if (p.length < suffix.length ||
            p.slice(p.length - suffix.length) !== suffix) return false;
        var startTs = Date.parse(r.created_at || '');
        return !isNaN(startTs) && !isNaN(sinceMs) && startTs >= sinceMs;
    });
}

